  "inlineSchema": "// Prisma schema for the H5P-style interactive learning app backend.\n//\n// Design notes:\n// - Subject/Module ids reuse the human-readable slugs already used by the\n//   frontend (e.g. \"ipas\", \"bilangan-cacah-1000\") so no remapping is needed.\n// - Frame uses a composite key (moduleId, slug) instead of a single global id,\n//   because frame ids (e.g. \"bc1\") are only unique *within* a module in the\n//   existing content, not globally.\n// - Frame-kind-specific fields (quiz questions, drag&drop items/zones, video\n//   markers, pdf src, short-answer items, text body) are stored in the `data`\n//   Json column rather than one column/table per kind. This keeps the schema\n//   simple and lets new frame kinds be added without a migration.\n// - Progress is tracked per anonymous `clientId` (a UUID the frontend\n//   generates and stores in localStorage) when nobody is logged in. Once a\n//   student logs in, the backend derives a canonical `clientId` of the form\n//   \"user:<userId>\" instead of trusting whatever the client sends — this\n//   keeps the ProgressRecord primary key shape unchanged while still letting\n//   us join back to a real User via the denormalized `userId` column below\n//   for report queries (\"this student's scores across every module\").\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  TEACHER\n  STUDENT\n}\n\nmodel User {\n  id           String           @id @default(cuid())\n  name         String\n  email        String           @unique\n  passwordHash String\n  role         Role\n  progress     ProgressRecord[]\n  sessions     Session[]\n  subscription Subscription?\n  payments     Payment[]\n  createdAt    DateTime         @default(now())\n  updatedAt    DateTime         @updatedAt\n\n  @@map(\"users\")\n}\n\n// A logged-in session, one per successful login/register/refresh. The\n// refresh token itself is never stored — only its SHA-256 hash — so a\n// leaked database dump can't be used to impersonate anyone (same rationale\n// as hashing passwords). Revoking a session (logout, or the user cabut-ing\n// a device from their session list) sets `revokedAt`, which immediately\n// invalidates that refresh token. The short-lived JWT access token it\n// already issued keeps working until its own ~15 minute expiry — this is\n// the standard, accepted trade-off of stateless access tokens.\nmodel Session {\n  id               String    @id @default(cuid())\n  userId           String\n  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  refreshTokenHash String    @unique\n  userAgent        String?\n  createdAt        DateTime  @default(now())\n  expiresAt        DateTime\n  revokedAt        DateTime?\n\n  @@index([userId])\n  @@map(\"sessions\")\n}\n\nmodel Subject {\n  id          String   @id\n  name        String\n  shortName   String\n  description String\n  icon        String\n  accent      String\n  modules     Module[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"subjects\")\n}\n\nmodel Module {\n  id               String   @id\n  subjectId        String\n  subject          Subject  @relation(fields: [subjectId], references: [id], onDelete: Restrict)\n  grade            Int\n  semester         Int\n  title            String\n  subtitle         String\n  summary          String\n  estimatedMinutes String\n  accent           String\n  frames           Frame[]\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([grade, semester, subjectId])\n  @@map(\"modules\")\n}\n\nmodel Frame {\n  moduleId String\n  module   Module  @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n  slug     String // original frame id within the module, e.g. \"bc1\"\n  kind     String // 'text' | 'quiz' | 'dragdrop' | 'video' | 'pdf' | 'shortanswer'\n  panel    String\n  title    String\n  note     String?\n  order    Int // preserves display/sidebar sequence within the module\n  data     Json // kind-specific payload, spread back onto the frame by the API\n\n  @@id([moduleId, slug])\n  @@index([moduleId, order])\n  @@map(\"frames\")\n}\n\nmodel ProgressRecord {\n  clientId  String // \"user:<userId>\" once logged in, else the anonymous UUID\n  moduleId  String\n  frameSlug String\n  userId    String? // set when clientId represents a logged-in user — enables report queries\n  user      User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  completed Boolean  @default(false)\n  correct   Int      @default(0)\n  total     Int      @default(0)\n  updatedAt DateTime @updatedAt\n\n  @@id([clientId, moduleId, frameSlug])\n  @@index([clientId, moduleId])\n  @@index([userId])\n  @@map(\"progress_records\")\n}\n\n// ---------- Billing / Subscription (Xendit) ----------\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELED\n  EXPIRED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  EXPIRED\n  FAILED\n}\n\nmodel Plan {\n  id        String   @id // 'free_trial' | 'basic' | 'pro'\n  name      String\n  priceIdr  Int // 0 for the free trial\n  interval  String // 'trial' | 'month'\n  trialDays Int? // only set for the free trial plan\n  features  Json // string[] of feature bullet points shown on the pricing page\n  createdAt DateTime @default(now())\n\n  subscriptions Subscription[]\n  payments      Payment[]\n\n  @@map(\"plans\")\n}\n\n// One active subscription per user. A brand-new account is auto-enrolled in\n// the free_trial plan at registration (see routes/auth.ts) so this always\n// exists once someone has an account — there's no \"no subscription\" state.\nmodel Subscription {\n  id               String             @id @default(cuid())\n  userId           String             @unique\n  user             User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  planId           String\n  plan             Plan               @relation(fields: [planId], references: [id], onDelete: Restrict)\n  status           SubscriptionStatus\n  currentPeriodEnd DateTime\n  createdAt        DateTime           @default(now())\n  updatedAt        DateTime           @updatedAt\n\n  @@map(\"subscriptions\")\n}\n\n// One row per Xendit invoice created for a paid-plan checkout attempt.\n// Starts PENDING; the Xendit webhook (routes/webhooks.ts) flips it to PAID\n// or EXPIRED once the customer finishes (or abandons) the hosted checkout.\nmodel Payment {\n  id               String        @id @default(cuid())\n  userId           String\n  user             User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  planId           String\n  plan             Plan          @relation(fields: [planId], references: [id], onDelete: Restrict)\n  amount           Int\n  status           PaymentStatus @default(PENDING)\n  xenditInvoiceId  String        @unique\n  xenditInvoiceUrl String\n  paidAt           DateTime?\n  createdAt        DateTime      @default(now())\n\n  @@index([userId])\n  @@map(\"payments\")\n}\n",
